fn solve(input: Vec<(i8, i8)>) -> Vec<i8> {
    let mut output = Vec::new();
    
    for i in 0..input.len() {
        let (a, b) = input[i];
        
        if a == b {
            output.push(0);
        } else {
            let diff = (b as i32) - (a as i32);
            
            let moves = if diff > 0 {
                // Positive difference: need to increase
                // Can increase by odd amounts in one move
                if diff % 2 == 1 {
                    1  // diff is odd, can do it in one move
                } else {
                    2  // diff is even, need two moves
                }
            } else {
                // Negative difference: need to decrease
                // Can decrease by even amounts in one move
                if diff % 2 == 0 {
                    1  // diff is even (negative even), can do it in one move
                } else {
                    2  // diff is odd (negative odd), need two moves
                }
            };
            
            output.push(moves);
        }
    }
    
    output
}